      const sqlText = `select sum(${quoted}id${quoted}) over(order by ${quoted}id${quoted} rows between ${dialect === 'postgres' ? '$1' : '?'} preceding and current row exclude ties) as ${quoted}sum${quoted}, lag(${quoted}id${quoted}, ${dialect === 'postgres' ? '$2, $3' : '?, ?'}) ignore nulls over(range unbounded preceding) as ${quoted}lag${quoted}, grouping(${quoted}gender${quoted}) as ${quoted}grouping${quoted} from ${quoted}person${quoted}`
      testSql(query, dialect, {
        postgres: { sql: sqlText, parameters: [2, 1, 0] },
        mysql: { sql: sqlText, parameters: [2, 1, 0] },
        mssql: { sql: sqlText, parameters: [2, 1, 0] },
        sqlite: { sql: sqlText, parameters: [2, 1, 0] },
      })
    })

    it('simplifies only implicit range defaults', () => {
      const query = ctx.db
        .withPlugin(new SimplifyFramePlugin())
        .selectFrom('person')
        .select((eb) => [
          eb.fn
            .sum<number>('id')
            .over((ob) =>
              ob
                .orderBy('id')
                .range((fb) => fb.betweenUnboundedPreceding().andCurrentRow()),
            )
            .as('ordered'),
          eb.fn
            .sum<number>('id')
            .over((ob) =>
              ob.range((fb) =>
                fb.betweenUnboundedPreceding().andUnboundedFollowing(),
              ),
            )
            .as('unordered'),
          eb.fn
            .sum<number>('id')
            .over((ob) =>
              ob.rows((fb) => fb.betweenUnboundedPreceding().andCurrentRow()),
            )
            .as('rows'),
        ])
      testSql(query, dialect, {
        postgres: {
          sql: `select sum("id") over(order by "id") as "ordered", sum("id") over() as "unordered", sum("id") over(rows between unbounded preceding and current row) as "rows" from "person"`,
          parameters: [],
        },
        mysql: {
          sql: `select sum(\`id\`) over(order by \`id\`) as \`ordered\`, sum(\`id\`) over() as \`unordered\`, sum(\`id\`) over(rows between unbounded preceding and current row) as \`rows\` from \`person\``,
          parameters: [],
        },
        mssql: {
          sql: `select sum("id") over(order by "id") as "ordered", sum("id") over() as "unordered", sum("id") over(rows between unbounded preceding and current row) as "rows" from "person"`,
          parameters: [],
